<?php declare(strict_types=1); namespace Annam; $title='Billing settings'; ?>
<form class="o-form" method="post"><?= csrf() ?><section class="o-card"><h2>Seller details</h2><p>These details appear on new bills. Issued bills retain their original details.</p><div class="o-grid-form"><?php foreach(['legal_name'=>'Legal business name','address'=>'Business address','state'=>'State','state_code'=>'State code','gstin'=>'GSTIN (when registered)','fssai_no'=>'FSSAI licence number','invoice_prefix'=>'Bill prefix','number_format'=>'Number format','tax_rate'=>'Default GST rate (%)','sac'=>'Default SAC / HSN','footer'=>'Bill footer'] as $key=>$label): ?><label class="o-field"><span><?= e($label) ?></span><?php if(in_array($key,['address','footer'])): ?><textarea name="<?= e($key) ?>"><?= e($profile[$key]) ?></textarea><?php else: ?><input name="<?= e($key) ?>" value="<?= e($profile[$key]) ?>"><?php endif; ?></label><?php endforeach; ?><label class="o-field">Tax registration<select name="gst_mode"><?php foreach(['unregistered'=>'Unregistered','regular'=>'Regular GST','composition'=>'Composition'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $profile['gst_mode']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label class="o-field">Issue bill<select name="bill_timing"><option value="on_payment" <?= $profile['bill_timing']==='on_payment'?'selected':'' ?>>When payment is received</option><option value="on_delivery" <?= $profile['bill_timing']==='on_delivery'?'selected':'' ?>>When delivered</option></select></label></div><?php foreach(['prices_include_tax'=>'Prices include tax','round_total'=>'Round total to nearest rupee','delivery_fee_taxable'=>'Apply GST to delivery fee'] as $key=>$label): ?><label class="php-switch-row"><input class="php-toggle" role="switch" type="checkbox" name="<?= e($key) ?>" value="1" <?= $profile[$key]?'checked':'' ?>><span><?= e($label) ?></span><b class="php-switch-state" aria-hidden="true"></b></label><?php endforeach; ?></section><button class="o-btn o-btn-primary">Save billing settings</button></form>
